const body = $input.first().json;
const vendors = body.vendors || (body.website ? [{ website: body.website, vendor_name: body.vendor_name || '' }] : []);
if (!vendors.length) throw new Error('vendors array required');
const rapidapi_key = (body.rapidapi_key || process.env.RAPIDAPI_KEY || '').trim();
if (!rapidapi_key) throw new Error('rapidapi_key required');
const admin_url = (body.admin_url || process.env.ADMIN_BASE_URL || 'http://127.0.0.1:8787').trim();
return vendors.map(v => ({ json: { website: v.website, vendor_name: v.vendor_name || '', rapidapi_key, admin_url } }));

const data = $input.first().json;
const website = $('Split Vendors').first().json.website;
const vendor_name = $('Split Vendors').first().json.vendor_name;

// Datagma field mapping
const company = data.company || data.data || data || {};

function formatFunding(amount, currency) {
  if (!amount || amount === 0) return null;
  const n = parseFloat(amount);
  if (isNaN(n)) return null;
  if (n >= 1_000_000_000) return `$${(n/1_000_000_000).toFixed(1)}B`;
  if (n >= 1_000_000) return `$${(n/1_000_000).toFixed(0)}M`;
  if (n >= 1_000) return `$${(n/1_000).toFixed(0)}K`;
  return `$${n.toFixed(0)}`;
}

const extracted = {};

// Founded year
const founded = company.yearFounded || company.founded_year || company.foundedOn || company.founded;
if (founded) extracted.founded = String(founded);

// HQ
const city = company.city || company.locality || '';
const region = company.region || company.state || '';
const country = company.country || company.country_code || '';
const hq_parts = [city, region, country].filter(Boolean);
if (hq_parts.length) extracted.hq_address = hq_parts.join(', ');
if (city || region) extracted.company_hq = [city, region].filter(Boolean).join(', ');

// Funding
const fundingStage = company.lastFundingType || company.funding_stage || company.last_funding_round_type;
if (fundingStage) extracted.funding_stage = fundingStage;

const totalFunding = formatFunding(company.totalFunding || company.total_funding_amount || company.fundingTotal);
if (totalFunding) extracted.total_funding = totalFunding;

// CEO / executive
const executives = company.executives || company.keyPeople || company.leadership || [];
if (Array.isArray(executives) && executives.length) {
  const ceo = executives.find(e => /ceo|chief executive|founder|co-founder/i.test(e.title || e.role || ''));
  if (ceo) {
    extracted.ceo_name = ceo.name || ceo.full_name || '';
    if (ceo.linkedin_url || ceo.linkedinUrl) extracted.ceo_linkedin = ceo.linkedin_url || ceo.linkedinUrl;
  }
}
// Fallback: direct CEO fields
if (!extracted.ceo_name && (company.ceo_name || company.ceoName)) {
  extracted.ceo_name = company.ceo_name || company.ceoName;
}

// Company size
const size = company.employeeCount || company.employee_count || company.headcount || company.companySize;
if (size) extracted.company_size = String(size);

// Revenue
const revenue = company.revenue || company.annualRevenue;
if (revenue) extracted.revenue = String(revenue);

// LinkedIn URL of company
if (company.linkedin_url || company.linkedinUrl) {
  extracted.linkedin_url = company.linkedin_url || company.linkedinUrl;
}

const has_data = Object.keys(extracted).length > 0;
return [{ json: { website, vendor_name, extracted, has_data, pipeline_name: 'csp-firmographic-enrichment' } }];
